diagrams.source:
flowchart TB
  MGMT@{ svc: "AWS Organizations", label: "管理アカウント（自動化は SCP の対象外）" }
  SCP@{ svc: "AWS Organizations", label: "✔ B: OU に SCP（StopLogging・DeleteTrail を拒否）" }
  MEM["メンバーアカウントの管理者・全員"]
  CT@{ svc: "AWS CloudTrail", label: "組織の証跡" }
  SCP == "✔ B: 管理者も止められない" ==> MEM
  MEM -. "停止の操作は拒否" .-> CT
  MGMT -- "引き続き管理できる" --> CT
  MEM -. "⚠ A: IAM ポリシーは管理者が外せる" .-> SCP

flowchart TB
  ROOT@{ svc: "AWS Organizations", label: "ルート: FullAWSAccess（許可）" }
  OU@{ svc: "AWS Organizations", label: "✔ B: Sandbox OU の SCP に DynamoDB を足す" }
  ACC@{ svc: "AWS Organizations", label: "メンバーアカウント: FullAWSAccess（許可）" }
  DEV@{ svc: "AWS IAM", label: "開発者の IAM ポリシー（DynamoDB を許可）" }
  ROOT -- "許可" --> OU
  OU == "✔ B: 欠けていた Allow を足す" ==> ACC
  ACC --> DEV
  OU -. "⚠ 今: S3 と EC2 だけ" .-> ACC
  DEV -. "⚠ A: IAM ポリシーを足しても SCP が拒否" .-> OU
